import {PLAN_ID,STORE,defaults,validateState,mergeState,isRead,dayDone,dayProgress,nextReading,readingVerses} from './model.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let plan,library,state=defaults(),all=[],byId,observer,currentReading=null,filter='all',query='',toastTimer,swReady,offlineBusy=false,aiBusy=false;
const icons={home:'⌂',plan:'▤',bookmarks:'◇',settings:'⚙'};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Не удалось сохранить отметки. Скачайте резервную копию в настройках.');}}
function appearance(){document.documentElement.dataset.theme=state.theme;document.documentElement.style.setProperty('--reader-size',state.font+'px');}
function url(r){return '#read/'+r.id;}
function heading(title,sub='',label='ВАШЕ ЛИЧНОЕ ЧТЕНИЕ'){return `<div class="heading"><span class="eyebrow">${label}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>`;}
function card(r,day){const done=isRead(state,r.id);return `<div class="reading-card ${done?'done':''}"><a class="reading-link" href="${url(r)}"><span class="book-mark" aria-hidden="true">${day?day.number:r.reference.split('.')[0]}</span><span><strong>${esc(r.title)}</strong><small>${esc(r.reference)} · ${done?'Прочитано':esc(r.section||'Синодальный перевод')}${day?' · День '+day.number:''}</small></span></a><button class="read-button" data-read="${r.id}" aria-label="${done?'Снять отметку':'Отметить прочитанным'}: ${esc(r.reference)}" aria-pressed="${done}">${done?'✓':'○'}</button></div>`;}
function sources(){return `<div class="sources">План — курс «Библия за год» проекта <a href="https://izuchaem-bibliu.ru/biblia-za-god" target="_blank" rel="noopener">«Исследуйте Писания»</a>.<br>Тексты — русский Синодальный перевод из <a href="https://lib.izuchaem-bibliu.ru/" target="_blank" rel="noopener">библиотеки курса</a>.<br>Приложение для личного чтения. Чтения и отметки доступны без интернета после сохранения библиотеки.</div>`;}
function home(){const next=nextReading(state,plan.days),complete=plan.days.filter(d=>dayDone(state,d)).length,read=all.filter(r=>isRead(state,r.id)).length;
  return heading(complete===365?'Вы прочитали весь план':'Читайте в своём темпе','Не нужно вспоминать, где остановились. Ваш следующий отрывок уже здесь.')+`<div class="dashboard"><div><section class="hero"><span class="eyebrow">${next?'СЛЕДУЮЩИЙ ШАГ':'ПЛАН ЗАВЕРШЁН'}</span><h2>${next?'День '+next.day.number+' из 365':'365 дней с Библией'}</h2><p>${next?esc(next.reading?.sourceLabel||'Назначения готовятся'):'Все отрывки отмечены прочитанными. Можно вернуться к закладкам или перечитать любой день.'}</p><a class="primary" href="${next?.reading?url(next.reading):'#plan'}">${next?.reading?'Продолжить чтение <span aria-hidden="true">→</span>':'Открыть план'}</a><p class="small-copy">${next?'Даже после перерыва вы продолжите с этого места.':'Ваши отметки сохранены на этом устройстве.'}</p></section>${next?`<div class="section-heading"><h2>День ${next.day.number}</h2><a href="#day/${next.day.number}">Все чтения дня →</a></div>${next.day.readings.map(r=>card(r)).join('')}`:''}</div><div><section class="card"><span class="eyebrow">ВАШ ПУТЬ</span><div class="progress-number">${complete} <small>из 365 дней</small></div><progress value="${complete}" max="365" aria-label="Полностью прочитанные дни"></progress><p class="small-copy">Прочитано отрывков: ${read} из ${all.length}.<br>Здесь нет просроченных дней — только ваше продвижение.</p></section><section class="card"><h2>Маленький шаг каждый день</h2><p class="small-copy">Читайте, отмечайте прочитанное и возвращайтесь, когда удобно.</p><a class="back" href="#settings">Сохранить для чтения без интернета →</a></section>${sources()}</div></div>`;
}
function dayPage(n){const d=plan.days.find(d=>d.number===n);if(!d)return empty('Такого дня нет','В плане 365 дней.','#plan','Открыть план');
  return `<div class="day-toolbar"><a class="back" href="#plan">← Весь план</a><div class="button-row"><a class="secondary" aria-label="Предыдущий день" ${n>1?'href="#day/'+(n-1)+'"':'aria-disabled="true"'}>←</a><a class="secondary" aria-label="Следующий день" ${n<365?'href="#day/'+(n+1)+'"':'aria-disabled="true"'}>→</a></div></div><div class="day-intro">${heading('День '+n,`${dayProgress(state,d)} из ${d.readings.length} отрывков прочитано`,'БИБЛИЯ ЗА ГОД')}<span class="day-count" aria-hidden="true">${String(n).padStart(2,'0')}</span></div>${(d.notes||[]).map(note=>`<p class="note">${esc(note)}</p>`).join('')}${d.readings.map(r=>card(r)).join('')}<p class="note">Нажмите на отрывок, чтобы читать. Кружок справа сохраняет отметку прочитанного.</p>${sources()}`;
}
function matches(d){return (filter!=='unread'||!dayDone(state,d))&&(filter!=='done'||dayDone(state,d))&&(!query||('день '+d.number+' '+d.readings.map(r=>r.title+' '+r.reference).join(' ')).toLowerCase().includes(query.toLowerCase()));}
function weeks(){const next=nextReading(state,plan.days)?.day.number||365;let html='',found=0;
  for(let i=0;i<365;i+=7){const week=plan.days.slice(i,i+7),days=week.filter(matches);if(!days.length)continue;found+=days.length;const count=week.filter(d=>dayDone(state,d)).length;
    html+=`<details class="week" ${query||filter!=='all'||(next>=i+1&&next<=i+7)?'open':''}><summary>Дни ${i+1}–${Math.min(i+7,365)}<span class="week-status">${count} / ${week.length} ✓</span></summary><div>${days.map(d=>`<a href="#day/${d.number}" class="plan-day ${dayDone(state,d)?'done':''}"><span class="number">${dayDone(state,d)?'✓':d.number}</span><span><span class="day-label">День ${d.number}</span><small>${esc(d.readings.map(r=>r.reference).join(' · '))}</small></span><span class="arrow" aria-hidden="true">→</span></a>`).join('')}</div></details>`;
  }
  return found?html:'<p class="note">По вашему запросу ничего не найдено.</p>';
}
function planPage(){return heading('План на 365 дней','Порядок чтений из годового плана курса. Начинайте с первого дня и двигайтесь без привязки к датам.')+`<div class="search-row"><input type="search" id="plan-search" placeholder="Найти книгу или день" aria-label="Поиск по плану" value="${esc(query)}"><form id="day-jump"><label for="day-number" class="muted">К дню </label><input id="day-number" type="number" min="1" max="365" required aria-label="Номер дня"><button class="secondary" type="submit">Перейти</button></form></div><div class="filters" aria-label="Фильтры плана">${[['all','Все дни'],['unread','Ещё не прочитано'],['done','Прочитано']].map(([v,t])=>`<button data-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div><div id="plan-weeks">${weeks()}</div>${sources()}`;}
function bookmarks(){const saved=all.filter(r=>state.bookmarks[r.id]);return heading('Закладки','Отрывки, к которым хочется вернуться.')+(saved.length?saved.map(r=>card(r,byId.get(r.id).day)).join(''):empty('Пока нет закладок','Откройте отрывок и нажмите «В закладки».','#plan','Открыть план'));}
function empty(title,sub,href,label){return `<div class="empty"><h2>${esc(title)}</h2><p>${esc(sub)}</p><a class="primary" href="${href}">${esc(label)}</a></div>`;}
function settings(){return heading('Настройки','Сделайте чтение удобным и сохраните свой прогресс.')+`<section class="card settings-section"><h2>Удобно читать</h2><label class="setting-row" for="font-size"><span>Размер букв <output id="font-value">${state.font}</output></span><input id="font-size" type="range" min="18" max="34" step="1" value="${state.font}"></label><label class="setting-row" for="theme"><span>Оформление</span><select id="theme"><option value="light" ${state.theme==='light'?'selected':''}>Светлое</option><option value="dark" ${state.theme==='dark'?'selected':''}>Тёмное</option></select></label><p class="sample">В начале сотворил Бог небо и землю.</p></section><section class="card settings-section"><h2>Без интернета</h2><p>Сохраните все 365 дней вместе с текстами. Дождитесь подтверждения, прежде чем отключать интернет.</p><div id="offline-status" class="status" role="status">Проверяем сохранённую библиотеку…</div><button class="primary wide" id="offline-save" ${offlineBusy?'disabled':''}>${offlineBusy?'Сохраняем…':'Сохранить для чтения без интернета'}</button><p class="small-copy">Пояснения ИИ требуют подключения к интернету. Браузер может удалить сохранённые файлы при нехватке места.</p></section><section class="card settings-section"><h2>Пояснения с ChatGPT</h2><p>Вопрос можно задать прямо при чтении отрывка. Пояснения доступны на подключённых устройствах владельца.</p><div class="status">ChatGPT пока не подключён. Платные запросы через AITunnel выключены.</div><p>Подключение потребует вашего входа в ChatGPT и разрешения на использование лимитов подписки.</p></section><section class="card settings-section"><h2>Мои отметки</h2><p>Отметки, закладки и место чтения хранятся на этом устройстве. Резервная копия поможет перенести их на другой телефон.</p><div class="button-row"><button class="primary" id="export-state">Скачать копию</button><button class="secondary" id="import-state">Восстановить из копии</button></div><input id="backup-file" type="file" accept="application/json,.json" hidden><p class="small-copy">При восстановлении ваши текущие отметки сохранятся и объединятся с копией.</p><button class="back" id="reset-state">Начать чтение заново</button></section><section class="card settings-section"><h2>Установить на телефон</h2><p>Добавьте приложение на главный экран, чтобы открывать его одним нажатием.</p><button class="secondary wide" data-install>Показать инструкцию</button></section>${sources()}`;}
function reader(r,day){const verses=readingVerses(r,library),done=isRead(state,r.id),index=all.findIndex(v=>v.id===r.id);let chapter=0;
  return `<div class="reader-toolbar"><a class="back" href="#day/${day.number}">← День ${day.number}</a><div class="font-controls"><button data-font="-2" aria-label="Уменьшить шрифт">А−</button><button data-font="2" aria-label="Увеличить шрифт">А+</button></div></div><header class="reader-heading"><span class="eyebrow">ДЕНЬ ${day.number} · ${esc(r.section||'БИБЛИЯ ЗА ГОД')}</span><h1>${esc(r.title)}</h1><p class="reference">${esc(r.reference)}</p><p class="muted">Русский Синодальный перевод</p><button class="secondary bookmark-button" data-bookmark="${r.id}" aria-pressed="${!!state.bookmarks[r.id]}">${state.bookmarks[r.id]?'◆ В закладках':'◇ В закладки'}</button></header>${r.sourceIssue?`<p class="note">${esc(r.sourceIssue)}</p>`:''}<article class="verses" aria-label="Текст Писания">${verses.map((v,i)=>{const h=chapter!==v.chapter&&r.start[0]!==r.end[0]?`<h2 class="chapter-label">Глава ${v.chapter}</h2>`:'';chapter=v.chapter;return h+`<p class="verse" id="verse-${i}" data-verse="${i}">${v.number===0?'':`<span class="verse-number" aria-label="Стих ${v.chapter}:${v.number}">${v.number}</span>`}${esc(v.text)}</p>`;}).join('')}</article><div class="reader-bottom"><div class="button-row"><button class="primary" data-read="${r.id}" aria-pressed="${done}">${done?'✓ Прочитано':'Отметить прочитанным'}</button><button class="secondary" id="explain">Пояснить отрывок</button></div><div class="button-row" style="margin-top:12px">${index>0?`<a class="secondary" href="${url(all[index-1])}">← Предыдущий</a>`:''}${index<all.length-1?`<a class="secondary" href="${url(all[index+1])}">Следующий →</a>`:'<a class="secondary" href="#home">На главную</a>'}</div><p class="reader-footer"><a href="${esc(r.source)}" target="_blank" rel="noopener">Открыть этот текст в библиотеке курса ↗</a></p></div>`;
}
function render(){if(!plan)return;observer?.disconnect();currentReading=null;document.body.classList.remove('reader-mode');const route=(location.hash||'#home').slice(1).split('/');let html='',section=route[0];
  if(section==='read'&&byId.has(route[1])){const {reading,day}=byId.get(route[1]);currentReading=reading;document.body.classList.add('reader-mode');html=reader(reading,day);}
  else if(section==='day')html=dayPage(Number(route[1]));else if(section==='plan')html=planPage();else if(section==='bookmarks')html=bookmarks();else if(section==='settings')html=settings();else{section='home';html=home();}
  $('#main').innerHTML=html;document.title=(currentReading?currentReading.reference:section==='day'?'День '+route[1]:({home:'Ваше чтение',plan:'План',bookmarks:'Закладки',settings:'Настройки'}[section]||'Ваше чтение'))+' · Библия за год';
  $('#navigation').innerHTML=[['home','Главная'],['plan','План'],['bookmarks','Закладки'],['settings','Настройки']].map(([id,t])=>`<a class="nav-item ${id===section||(section==='day'&&id==='plan')?'active':''}" ${id===section?'aria-current="page"':''} href="#${id}"><span class="nav-icon" aria-hidden="true">${icons[id]}</span>${t}</a>`).join('');
  window.scrollTo(0,0);$('#main').focus({preventScroll:true});if(currentReading){const id=currentReading.id,position=state.positions[id];if(position)requestAnimationFrame(()=>$('#verse-'+position)?.scrollIntoView());
    observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top);if(visible.length){state.positions[id]=Number(visible[0].target.dataset.verse);save();}},{rootMargin:'-90px 0px -65% 0px'});document.querySelectorAll('.verse').forEach(v=>observer.observe(v));
  }if(section==='settings'){offlineStatus();loadAISettings();}
}
function toggleRead(id){if(!byId.has(id))return;if(isRead(state,id))delete state.read[id];else state.read[id]=true;save();if(currentReading){const b=$('[data-read]');b.setAttribute('aria-pressed',isRead(state,id));b.textContent=isRead(state,id)?'✓ Прочитано':'Отметить прочитанным';}else{const y=scrollY;render();window.scrollTo(0,y);}toast(isRead(state,id)?'Отрывок отмечен прочитанным':'Отметка снята');}
function confirmAction(title,text,fn){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-action').onclick=()=>{$('#confirm-dialog').close();fn();};$('#confirm-dialog').showModal();}
function exportState(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='bible-year-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Копия подготовлена. Сохраните скачанный файл.');}
async function importState(file){if(!file)return;if(file.size>2_000_000)return toast('Файл слишком большой. Выберите резервную копию этого приложения.');try{const incoming=validateState(JSON.parse(await file.text()),new Set(byId.keys()));confirmAction('Восстановить отметки?','Текущие отметки и закладки объединятся с копией. Размер шрифта и оформление будут взяты из копии.',()=>{state=mergeState(state,incoming);save();appearance();render();toast('Отметки и закладки восстановлены');});}catch(e){toast('Не удалось прочитать копию: '+e.message);}}
async function offlineStatus(){try{const registration=await swReady;if(!registration)throw Error();const data=await swMessage('STATUS');const el=$('#offline-status');if(el)el.textContent=data.ready?'Все тексты сохранены. Можно читать без интернета.':'Библиотека ещё не сохранена полностью.';if($('#offline-save'))$('#offline-save').textContent=data.ready?'Обновить сохранённую библиотеку':'Сохранить для чтения без интернета';}catch{if($('#offline-status'))$('#offline-status').textContent='Сохранение пока недоступно. Откройте приложение по HTTPS и обновите страницу.';}}
function swMessage(type){return new Promise(async(resolve,reject)=>{try{const reg=await swReady,worker=navigator.serviceWorker.controller||reg?.active;if(!worker)return reject(Error('Нет обработчика сохранения'));const channel=new MessageChannel(),timer=setTimeout(()=>reject(Error('Истекло время ожидания')),180000);channel.port1.onmessage=e=>{clearTimeout(timer);e.data.ok?resolve(e.data):reject(Error(e.data.error||'Не удалось сохранить'));};worker.postMessage({type},[channel.port2]);}catch(e){reject(e);}});}
async function offlineSave(){if(offlineBusy)return;offlineBusy=true;if($('#offline-save')){$('#offline-save').disabled=true;$('#offline-save').textContent='Сохраняем все тексты…';}try{await swMessage('SAVE');if(navigator.storage?.persist)await navigator.storage.persist();toast('Все 365 дней и тексты сохранены для чтения без интернета.');}catch(e){toast('Сохранение не завершено. Проверьте интернет и свободное место.');}finally{offlineBusy=false;if($('#offline-save'))$('#offline-save').disabled=false;offlineStatus();}}
async function aiStatus(){try{const r=await fetch('./api/status',{cache:'no-store',signal:AbortSignal.timeout(5000)});if(!r.ok)throw Error();return await r.json();}catch{return {ready:false,canConnect:false};}}
async function loadAISettings(){const box=[...document.querySelectorAll('.settings-section')].find(x=>x.querySelector('h2')?.textContent==='Пояснения с ChatGPT');if(!box)return;const status=await aiStatus();if(!box.isConnected)return;
  box.innerHTML=`<h2>Пояснения с ChatGPT</h2><p>Выбранный отрывок и ваш вопрос передаются в OpenAI. Ответ появится прямо в приложении.</p><div class="status" role="status">${status.ready?'Ваша подписка подключена. Пояснения расходуют её общие лимиты.':esc(status.error||(status.remote&&!status.owner?'ChatGPT пока не подключён на этом устройстве.':'ChatGPT пока не подключён. Запросы не отправляются.'))}</div>${status.ready?'<button class="secondary" id="ai-disconnect">Отключить ChatGPT на всех устройствах</button>':status.canConnect?'<button class="primary" id="ai-connect">Continue with ChatGPT</button><div id="ai-signin-link"></div><p class="small-copy">На странице OpenAI проверьте аккаунт и разрешение на использование подписки.</p>':status.remote?'<button class="primary" id="ai-connect-guide">Подключить ChatGPT</button><p class="small-copy">Первый вход выполняется на компьютере. Затем можно подключить телефон. Читать и отмечать отрывки можно без ИИ.</p>':'<p class="small-copy">Сервис пояснений сейчас недоступен. Проверьте интернет.</p>'}${status.remote&&status.owner?'<div class="button-row" style="margin-top:16px"><button class="primary" id="ai-device-link">Подключить телефон</button><button class="secondary" id="ai-device-logout">Выйти на этом устройстве</button></div><div id="ai-device-result" aria-live="polite"></div>':''}`;
}
function connectGuide(){let dialog=$('#ai-setup-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='ai-setup-dialog';document.body.append(dialog);}dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Закрыть">×</button><h2>Подключить ChatGPT</h2><p>Первый вход выполните на вашем компьютере: откроется страница OpenAI для подключения подписки.</p><a class="primary wide" href="http://127.0.0.1:8769/" target="_blank" rel="noopener noreferrer">Continue with ChatGPT ↗</a><p class="small-copy">Если окно подключения не открывается, помощник входа на компьютере нужно запустить заново.</p><h3>Если вы на телефоне</h3><p>После входа на компьютере откройте в приложении «Настройки → Подключить телефон». Отправьте одноразовую ссылку себе и откройте её на телефоне.</p><p class="small-copy">Пароль ChatGPT вводится только на странице OpenAI. В приложение и в чат его присылать не нужно.</p>`;dialog.showModal();}
async function deviceLink(){try{const r=await fetch('./api/auth/device',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),data=await r.json();if(!r.ok)throw Error(data.error);const target=new URL(data.url);if(target.origin!==location.origin)throw Error('Неверный адрес подключения');$('#ai-device-result').innerHTML=`<p>Откройте эту ссылку на своём телефоне. Она действует 10 минут и только один раз. Ссылка даёт доступ к пояснениям через вашу подписку — не публикуйте её.</p><label for="device-link">Ссылка подключения</label><input class="device-link" id="device-link" type="text" readonly value="${esc(data.url)}"><button class="secondary wide" id="ai-copy-device">Скопировать ссылку</button>`;}catch(e){toast(e.message);}}
async function connectAI(){const button=$('#ai-connect');if(button){button.disabled=true;button.textContent='Подготавливаем вход…';}try{const r=await fetch('./api/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();let target;for(let n=0;n<20;n++){const data=await(await fetch('./api/connect-url',{cache:'no-store'})).json();if(data.url){target=data.url;break;}await new Promise(r=>setTimeout(r,250));}if(!target||new URL(target).origin!=='https://auth.openai.com')throw Error();$('#ai-signin-link').innerHTML=`<a class="primary wide" href="${esc(target)}" target="_blank" rel="noopener noreferrer">Continue with ChatGPT ↗</a><p class="small-copy">После входа вернитесь в приложение.</p>`;if(button)button.hidden=true;}catch{toast('Не удалось подготовить вход. Попробуйте ещё раз.');if(button){button.disabled=false;button.textContent='Continue with ChatGPT';}}}
async function explain(){let dialog=$('#ai-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='ai-dialog';document.body.append(dialog);}const reading=currentReading;
  if(dialog.dataset.readingId===reading.id&&dialog.querySelector('#ai-question-form')){dialog.showModal();return;}dialog.dataset.readingId=reading.id;
  dialog.innerHTML=`<button class="dialog-close" data-close aria-label="Закрыть">×</button><span class="eyebrow">РАЗОБРАТЬСЯ В ПРОЧИТАННОМ</span><h2>Пояснение отрывка</h2><p class="muted">${esc(reading.reference)}</p><div id="ai-content" role="status">Проверяем подключение…</div>`;dialog.showModal();const status=await aiStatus();if(!dialog.open)return;
  if(!status.ready){$('#ai-content').innerHTML='<p>Ваша подписка ChatGPT пока не подключена. Запросы не отправляются.</p><a class="primary wide" href="#settings" data-close>Подключить в настройках</a>';return;}
  $('#ai-content').innerHTML=`<form id="ai-question-form"><input type="hidden" name="readingId" value="${reading.id}"><label for="ai-model">Модель ChatGPT</label><select id="ai-model" name="model">${status.models.map(m=>`<option value="${esc(m.slug)}">${esc(m.display_name)}</option>`).join('')}</select><label for="ai-question">Что хотите понять?</label><textarea id="ai-question" name="question" maxlength="1500" rows="4" required placeholder="Объясни смысл этого отрывка простыми словами"></textarea><div class="ai-quick">${['Объясни простыми словами','Расскажи об историческом контексте','Поясни непонятные слова'].map(q=>`<button type="button" class="secondary" data-question="${q}">${q}</button>`).join('')}</div><p class="small-copy">В OpenAI будут переданы этот отрывок и ваш вопрос. Используются лимиты вашей подписки. В приложении — до 30 пояснений в день.</p><button class="primary wide" type="submit" ${aiBusy?'disabled':''}>${aiBusy?'Готовим пояснение…':'Получить пояснение'}</button></form><div id="ai-answer" aria-live="polite"></div><p class="small-copy">Пояснение ИИ может содержать ошибки. Оно не заменяет толкования и беседу со священником.</p>`;
}
function answerMarkup(raw){const inline=t=>esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');return String(raw).split(/\n\s*\n/).map(block=>{const lines=block.split('\n');return lines.every(l=>/^[-*] /.test(l))?'<ul>'+lines.map(l=>'<li>'+inline(l.slice(2))+'</li>').join('')+'</ul>':'<p>'+inline(block).replace(/\n/g,'<br>')+'</p>';}).join('');}
async function sendQuestion(form){if(aiBusy)return;aiBusy=true;const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent='Готовим пояснение…';const answer=$('#ai-answer');answer.textContent='';try{const data=Object.fromEntries(new FormData(form)),r=await fetch('./api/explain',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(100000)}),result=await r.json();if(!r.ok)throw Error(result.error||'Пояснение сейчас недоступно');const label=document.createElement('h3');label.textContent='Пояснение ИИ · '+result.reference;const text=document.createElement('div');text.className='ai-answer-text';text.innerHTML=answerMarkup(result.answer);answer.append(label,text);}catch(e){answer.textContent=e.name==='TimeoutError'?'Ответ не успел прийти. Попробуйте позже.':e.message;}finally{aiBusy=false;button.disabled=false;button.textContent='Получить пояснение';}}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.matches('[data-close]'))b.closest('dialog')?.close();else if(b.matches('[data-cancel]'))$('#confirm-dialog').close();else if(b.matches('[data-install],#install-help'))$('#help-dialog').showModal();else if(b.dataset.read)toggleRead(b.dataset.read);else if(b.dataset.bookmark){const id=b.dataset.bookmark;if(state.bookmarks[id])delete state.bookmarks[id];else state.bookmarks[id]=true;save();b.setAttribute('aria-pressed',!!state.bookmarks[id]);b.textContent=state.bookmarks[id]?'◆ В закладках':'◇ В закладки';toast(state.bookmarks[id]?'Закладка сохранена':'Закладка удалена');}else if(b.dataset.font){state.font=Math.max(18,Math.min(34,state.font+Number(b.dataset.font)));appearance();save();toast('Размер букв: '+state.font);}else if(b.dataset.filter){filter=b.dataset.filter;render();}else if(b.id==='export-state')exportState();else if(b.id==='import-state')$('#backup-file').click();else if(b.id==='reset-state')confirmAction('Начать с первого дня?','Отметки прочитанного и место чтения будут удалены на этом устройстве. Закладки и настройки сохранятся. Сначала можно скачать копию.',()=>{state.read={};state.positions={};save();render();toast('Можно начать с первого дня');});else if(b.id==='offline-save')offlineSave();else if(b.id==='explain')explain();});
document.addEventListener('input',e=>{if(e.target.id==='font-size'){state.font=Number(e.target.value);appearance();save();$('#font-value').textContent=state.font;}if(e.target.id==='plan-search'){query=e.target.value;$('#plan-weeks').innerHTML=weeks();}});
document.addEventListener('change',e=>{if(e.target.id==='theme'){state.theme=e.target.value;appearance();save();}if(e.target.id==='backup-file')importState(e.target.files[0]);});
document.addEventListener('submit',e=>{if(e.target.id==='ai-question-form'){e.preventDefault();sendQuestion(e.target);}if(e.target.id==='day-jump'){e.preventDefault();const n=Number($('#day-number').value);if(n>=1&&n<=365)location.hash='#day/'+n;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='ai-connect-guide')connectGuide();if(b.id==='ai-connect')connectAI();if(b.id==='ai-device-link')deviceLink();if(b.id==='ai-copy-device'){try{await navigator.clipboard.writeText($('#device-link').value);toast('Ссылка скопирована. Откройте её на своём телефоне.');}catch{$('#device-link').select();toast('Выделена ссылка — скопируйте её.');}}if(b.id==='ai-device-logout'){try{const r=await fetch('./api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();await loadAISettings();toast('Вы вышли на этом устройстве');}catch{toast('Не удалось выйти. Проверьте интернет.');}}if(b.dataset.question&&$('#ai-question'))$('#ai-question').value=b.dataset.question;if(b.id==='ai-disconnect'){try{const r=await fetch('./api/disconnect',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),data=await r.json();if(!r.ok)throw Error(data.error);await loadAISettings();toast(data.revoked?'ChatGPT отключён':'Подключение удалено здесь. Отзыв доступа проверьте в настройках ChatGPT.');}catch(e){toast(e.message);}}});
window.addEventListener('focus',()=>{if(location.hash==='#settings')loadAISettings();});
window.addEventListener('hashchange',render);window.addEventListener('pagehide',save);window.addEventListener('storage',e=>{if(e.key!==STORE||!plan)return;try{state=e.newValue?validateState(JSON.parse(e.newValue),new Set(byId.keys())):defaults();appearance();render();}catch{}});
async function start(){try{
  const pairing=location.hash.match(/^#owner\/([A-Za-z0-9_-]{43})$/);if(pairing){history.replaceState(null,'',location.pathname+location.search+'#settings');try{const response=await fetch('./api/auth/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:pairing[1]})}),result=await response.json();toast(response.ok?'Устройство подключено к пояснениям':result.error||'Не удалось подключить устройство');}catch{toast('Не удалось подключить устройство. Проверьте интернет и откройте ссылку ещё раз.');}}

  swReady='serviceWorker'in navigator?navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(()=>navigator.serviceWorker.ready).catch(()=>null):Promise.resolve(null);
  const responses=await Promise.all(['plan','library'].map(n=>fetch('./data/'+n+'.json')));if(responses.some(r=>!r.ok))throw Error('Данные недоступны');[plan,library]=await Promise.all(responses.map(r=>r.json()));if(plan.schema!==1||plan.planId!==PLAN_ID)throw Error('Неподдерживаемый план');
  all=plan.days.flatMap(d=>d.readings);byId=new Map(plan.days.flatMap(day=>day.readings.map(reading=>[reading.id,{day,reading}])));try{const raw=localStorage.getItem(STORE);if(raw)state=validateState(JSON.parse(raw),new Set(byId.keys()));}catch{toast('Не удалось прочитать сохранённые настройки. Восстановите их из резервной копии.');}appearance();render();
}catch(e){$('#main').innerHTML=empty('Не удалось открыть библиотеку','Проверьте интернет. Для чтения без сети библиотеку нужно заранее сохранить в настройках.','#home','Попробовать ещё раз');$('#main a').addEventListener('click',()=>location.reload());}}
start();
